#!/usr/bin/env python3
"""Merge locale JSON modules and emit a static C++ string table for taiji-tui."""
from __future__ import annotations

import sys
from pathlib import Path

from locale_lib import LocaleManifest, flatten, validate_locales, write_key_catalog


def escape_cpp(text: str) -> str:
    return (
        text.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
    )


def emit_go(entries: list[tuple[str, str, str, str]], output: Path) -> None:
    lines = [
        "// Code generated by scripts/embed_locales.py. DO NOT EDIT.",
        "package uilocale",
        "",
        "type catalogEntry struct {",
        "    locale string",
        "    module string",
        "    key    string",
        "    value  string",
        "}",
        "",
        "var catalogEntries = []catalogEntry{",
    ]
    for locale_id, module, key, value in entries:
        lines.append(
            f'    {{locale: "{escape_cpp(locale_id)}", module: "{escape_cpp(module)}", '
            f'key: "{escape_cpp(key)}", value: "{escape_cpp(value)}"}},'
        )
    lines.extend(
        [
            "}",
            "",
        ]
    )
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text("\n".join(lines), encoding="utf-8")


def main() -> int:
    if len(sys.argv) < 3:
        print(
            "usage: embed_locales.py <locales_dir> <output.cpp> [--go <catalog_gen.go>]",
            file=sys.stderr,
        )
        return 1

    locales_dir = Path(sys.argv[1])
    output = Path(sys.argv[2])
    go_output: Path | None = None
    if len(sys.argv) >= 5 and sys.argv[3] == "--go":
        go_output = Path(sys.argv[4])

    manifest = LocaleManifest.load(locales_dir)
    issues, _coverages = validate_locales(manifest)
    blocking = [issue for issue in issues if issue.kind == "unknown_key"]
    if blocking:
        print("embed_locales.py: fix unknown locale keys before building:", file=sys.stderr)
        for issue in blocking:
            print(f"  {issue.locale} {issue.module}.{issue.key}: {issue.message}", file=sys.stderr)
        return 1

    write_key_catalog(manifest, locales_dir / "key-catalog.json")

    entries: list[tuple[str, str, str, str]] = []
    for locale_id in manifest.locale_ids:
        for module in manifest.modules:
            base = manifest.merged_module(locale_id, module)
            for key, value in flatten(base):
                entries.append((locale_id, module, key, value))

    lines = [
        "// Generated by scripts/embed_locales.py. Do not edit.",
        '#include "ui_locales_embed.hpp"',
        "",
        "namespace taiji_locales_embed {",
        "",
        "const LocaleString kStrings[] = {",
    ]
    for locale_id, module, key, value in entries:
        lines.append(
            f'    {{"{escape_cpp(locale_id)}", "{escape_cpp(module)}", '
            f'"{escape_cpp(key)}", "{escape_cpp(value)}"}},'
        )
    lines.extend(
        [
            "};",
            "",
            f"const std::size_t kStringCount = {len(entries)};",
            "",
            "const char* const kLocaleIds[] = {",
        ]
    )
    for locale_id in manifest.locale_ids:
        lines.append(f'    "{escape_cpp(locale_id)}",')
    lines.extend(
        [
            "};",
            "",
            f"const std::size_t kLocaleIdCount = {len(manifest.locale_ids)};",
            "",
            "} // namespace taiji_locales_embed",
            "",
        ]
    )
    output.write_text("\n".join(lines), encoding="utf-8")
    if go_output is not None:
        emit_go(entries, go_output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
